toolScript:
(() => {
  const MODELS = {
    llama3_8b: { b: 8.03, layers: 32, kvHeads: 8, headDim: 128 },
    llama3_70b: { b: 70.6, layers: 80, kvHeads: 8, headDim: 128 },
    mistral_7b: { b: 7.24, layers: 32, kvHeads: 8, headDim: 128 },
    gemma2_9b: { b: 9.24, layers: 42, kvHeads: 8, headDim: 256 },
    gemma2_27b: { b: 27.2, layers: 46, kvHeads: 16, headDim: 128 },
    qwen25_7b: { b: 7.61, layers: 28, kvHeads: 4, headDim: 128 },
    qwen25_14b: { b: 14.7, layers: 48, kvHeads: 8, headDim: 128 },
    qwen25_72b: { b: 72.7, layers: 80, kvHeads: 8, headDim: 128 },
    deepseek_coder_33b: { b: 33.2, layers: 62, kvHeads: 8, headDim: 128 },
  };

  const QUANTS = {
    fp16: { bits: 16.0, desc: 'Exact full weights. Highest memory demand, zero quantization perplexity loss.' },
    q8_0: { bits: 8.5, desc: 'Near-lossless 8-bit integer quantization. Minimal reasoning degradation vs FP16.' },
    q6_k: { bits: 6.56, desc: 'High-fidelity k-quant. Perplexity degradation is imperceptible in practice.' },
    q5_k_m: { bits: 5.5, desc: 'Balanced sweet-spot for most models. Excellent reasoning retention.' },
    q4_k_m: { bits: 4.5, desc: 'The standard community default for local LLM inference. Fits most consumer GPUs.' },
    q3_k_s: { bits: 3.44, desc: 'Compact quantization. Noticeable perplexity degradation on code/math tasks.' },
    iq2_xs: { bits: 2.31, desc: 'Extreme compression. Fits 70B models on 24GB GPUs at the expense of output quality.' },
  };

  let kvPrecisionBytes = 2; // 2 for FP16, 1 for FP8

  const modelSelect = document.getElementById('llm-model-select');
  const customParamsBox = document.getElementById('llm-custom-params');
  const customB = document.getElementById('llm-custom-b');
  const customLayers = document.getElementById('llm-custom-layers');
  const customKvHeads = document.getElementById('llm-custom-kv-heads');
  const quantSelect = document.getElementById('llm-quant-select');
  const quantDesc = document.getElementById('llm-quant-desc');
  const contextSlider = document.getElementById('llm-context-slider');
  const contextDisplay = document.getElementById('llm-context-display');
  const kvFp16Btn = document.getElementById('llm-kv-fp16-btn');
  const kvFp8Btn = document.getElementById('llm-kv-fp8-btn');

  const totalVramEl = document.getElementById('llm-total-vram');
  const weightsVramEl = document.getElementById('llm-weights-vram');
  const kvVramEl = document.getElementById('llm-kv-vram');
  const cudaVramEl = document.getElementById('llm-cuda-vram');
  const barWeights = document.getElementById('llm-bar-weights');
  const barKv = document.getElementById('llm-bar-kv');
  const barCuda = document.getElementById('llm-bar-cuda');

  const fit8Gb = document.getElementById('llm-fit-8gb');
  const fit12Gb = document.getElementById('llm-fit-12gb');
  const fit16Gb = document.getElementById('llm-fit-16gb');
  const fit24Gb = document.getElementById('llm-fit-24gb');
  const fitMac = document.getElementById('llm-fit-mac');
  const offloadAdvice = document.getElementById('llm-offload-advice');

  function getModelParams() {
    const val = modelSelect.value;
    if (val === 'custom') {
      return {
        b: parseFloat(customB.value) || 8.0,
        layers: parseInt(customLayers.value, 10) || 32,
        kvHeads: parseInt(customKvHeads.value, 10) || 8,
        headDim: 128,
      };
    }
    return MODELS[val] || MODELS.llama3_8b;
  }

  function setBadge(el, fits) {
    if (fits) {
      el.textContent = 'Supported';
      el.className = 'px-2 py-0.5 rounded font-bold text-[10px] bg-emerald-100 text-emerald-800';
    } else {
      el.textContent = 'Insufficient VRAM';
      el.className = 'px-2 py-0.5 rounded font-bold text-[10px] bg-rose-100 text-rose-800';
    }
  }

  function update() {
    const m = getModelParams();
    const q = QUANTS[quantSelect.value] || QUANTS.q4_k_m;
    quantDesc.textContent = q.desc;

    const contextTokens = parseInt(contextSlider.value, 10);
    contextDisplay.textContent = contextTokens.toLocaleString() + ' tokens';

    // Weights VRAM (GiB)
    const rawWeightBytes = m.b * 1e9 * (q.bits / 8);
    const weightsGb = rawWeightBytes / (1024 * 1024 * 1024);

    // KV Cache VRAM (GiB)
    const rawKvBytes = 2 * m.layers * m.kvHeads * m.headDim * contextTokens * kvPrecisionBytes;
    const kvGb = rawKvBytes / (1024 * 1024 * 1024);

    // CUDA Overhead
    const activationBufferGb = (contextTokens / 32768) * 0.4;
    const cudaGb = 0.8 + activationBufferGb;

    const totalGb = weightsGb + kvGb + cudaGb;

    totalVramEl.textContent = totalGb.toFixed(2) + ' GB';
    weightsVramEl.textContent = weightsGb.toFixed(2) + ' GB';
    kvVramEl.textContent = kvGb.toFixed(2) + ' GB';
    cudaVramEl.textContent = cudaGb.toFixed(2) + ' GB';

    const wPct = (weightsGb / totalGb) * 100;
    const kPct = (kvGb / totalGb) * 100;
    const cPct = 100 - wPct - kPct;
    barWeights.style.width = wPct.toFixed(1) + '%';
    barKv.style.width = kPct.toFixed(1) + '%';
    barCuda.style.width = cPct.toFixed(1) + '%';

    setBadge(fit8Gb, totalGb <= 7.5);
    setBadge(fit12Gb, totalGb <= 11.5);
    setBadge(fit16Gb, totalGb <= 15.2);
    setBadge(fit24Gb, totalGb <= 23.2);

    if (totalGb <= 16) {
      fitMac.textContent = 'M-Series 18GB+ Base';
      fitMac.className = 'px-2 py-0.5 rounded font-bold text-[10px] bg-emerald-100 text-emerald-800';
    } else if (totalGb <= 32) {
      fitMac.textContent = 'M-Series 36GB+ Unified';
      fitMac.className = 'px-2 py-0.5 rounded font-bold text-[10px] bg-emerald-100 text-emerald-800';
    } else if (totalGb <= 60) {
      fitMac.textContent = 'M-Series 64GB+ Pro/Max';
      fitMac.className = 'px-2 py-0.5 rounded font-bold text-[10px] bg-indigo-100 text-indigo-800';
    } else {
      fitMac.textContent = 'Mac Studio 128GB+ Ultra';
      fitMac.className = 'px-2 py-0.5 rounded font-bold text-[10px] bg-purple-100 text-purple-800';
    }

    // Layer Offload Estimate for 16GB GPU
    const target16Gb = 16.0;
    const availableForWeights = Math.max(0, target16Gb - kvGb - cudaGb);
    const vramPerLayer = weightsGb / m.layers;
    const offloadable = Math.min(m.layers, Math.floor(availableForWeights / Math.max(0.01, vramPerLayer)));

    if (offloadable >= m.layers) {
      offloadAdvice.textContent = `Can offload all ${m.layers} of ${m.layers} layers to GPU for 100% native acceleration.`;
    } else if (offloadable > 0) {
      offloadAdvice.textContent = `Can offload approximately ${offloadable} of ${m.layers} layers to a 16 GB GPU (remaining ${m.layers - offloadable} layers in system RAM).`;
    } else {
      offloadAdvice.textContent = `Model too large for a 16 GB GPU. Full execution in system RAM or larger GPU recommended.`;
    }
  }

  modelSelect.addEventListener('change', () => {
    if (modelSelect.value === 'custom') {
      customParamsBox.classList.remove('hidden');
    } else {
      customParamsBox.classList.add('hidden');
    }
    update();
  });

  quantSelect.addEventListener('change', update);
  contextSlider.addEventListener('input', update);
  customB.addEventListener('input', update);
  customLayers.addEventListener('input', update);
  customKvHeads.addEventListener('input', update);

  kvFp16Btn.addEventListener('click', () => {
    kvPrecisionBytes = 2;
    kvFp16Btn.className = 'px-3 py-1.5 rounded-lg bg-slate-900 text-white font-bold text-xs';
    kvFp8Btn.className = 'px-3 py-1.5 rounded-lg border border-slate-300 bg-white text-slate-700 font-bold text-xs hover:bg-slate-100';
    update();
  });

  kvFp8Btn.addEventListener('click', () => {
    kvPrecisionBytes = 1;
    kvFp8Btn.className = 'px-3 py-1.5 rounded-lg bg-slate-900 text-white font-bold text-xs';
    kvFp16Btn.className = 'px-3 py-1.5 rounded-lg border border-slate-300 bg-white text-slate-700 font-bold text-xs hover:bg-slate-100';
    update();
  });

  update();
})();
